  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C01"],
      "claim": "A close piperazine-amide analogue readily passed the BBB with high brain and spinal cord levels in mice, supporting CNS access for the query's similar piperazine-aryl amide scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "A piperazine-amide analogue showed brain-to-serum AUC ratios greater than 1 in mice after both i.p. and p.o. dosing, demonstrating robust BBB penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "A piperazine-amide H3 receptor ligand crossed the BBB with a brain-to-plasma ratio of about 1:1 in rats, directly indicating good CNS penetration for this chemotype.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "An aryl-pyridazine piperazine analogue, structurally close to the query's nitrile-pyridazine piperazine, showed high brain uptake in mice, supporting CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "An isopropylphenyl amide/heteroaryl analogue had a brain/plasma ratio of 1.66 in rats and was classified as good CNS penetration, supporting the query's similar lipophilic features.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "An isopropylpiperazine biarylamide analogue traversed the BBB and displayed excellent brain drug levels in mice after oral dosing, supporting meaningful CNS access for the query.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues consistently demonstrate good-to-excellent brain penetration, including brain/plasma ratios ≥1, high brain uptake, and central pharmacodynamic effects. The query shares the same piperazine-amide and aryl-heteroaryl lipophilic scaffold, so meaningful CNS access is strongly supported.",
  "evidence_gaps": [
    "No direct query-specific pharmacokinetic measurement is available.",
    "No explicit P-glycoprotein/efflux transporter assessment is reported for the query.",
    "Unbound brain or CSF concentrations are not directly measured, though total brain exposure evidence is strong."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

